// Phase 6: find leads that have gone quiet.
//
// A lead is "silent" when:
//   - it is still open (not WON / LOST / DISQUALIFIED)
//   - we sent them something at least SILENCE_HOURS ago
//   - they have not replied since our last outbound
//   - we have not already escalated them for THIS silence episode
//
// 30 Aug 2026 - three confirmed defects fixed here.
//
// D1 IDENTITY. communication_logs.lead_email holds whatever the workflow that
//    wrote the row happened to have: a real email, a raw WhatsApp chat id
//    (`<digits>@c.us`, `<lid>@lid`) or the synthetic `+<digits>@whatsapp.lead`.
//    The old code indexed the logs by lead_email and looked up ONLY
//    String(lead.email), then did `if (!rows.length) continue`. Every
//    WhatsApp-only lead therefore fell out silently and the hourly job ran
//    green with zero output - in a Dubai used-car dealership that is most of
//    the book. We now build the full set of plausible identity keys per lead
//    and match any of them. Same shape as `Fetch Thread History` in the
//    WhatsApp BDC workflow, which queries `or=(lead_email.eq.<k>,...)`.
//    A LID chat id contains no phone digits at all, so it cannot be derived
//    from the lead - those are bridged through whatsapp_contacts
//    (chat_id -> phone / lead_email), the same table the BDC workflow upserts.
//
// D3 MARKER EXPIRY. The old check was `rows.some(r => startsWith(MARKER))`
//    against ALL history, so one escalation retired a lead from the safety net
//    forever: escalated in March, silent again in August, never surfaced.
//    A marker now only suppresses when it belongs to the CURRENT episode, i.e.
//    it was written at or after our last real outbound message. Marker rows are
//    also excluded from the outbound set - written as they were with
//    direction 'outbound', they reset lastOut and reset hours_silent to zero.
//
// BOUNDED WORK. The escalation sub-workflow runs an AI agent per lead and is
//    called with waitForSubWorkflow, so the run length is linear in the number
//    of silent leads. workflow executionTimeout is 300s: an unbounded backlog
//    (first run after this fix will surface every WhatsApp lead ever) would be
//    killed mid-loop, leaving leads escalated but unmarked. Highest ai_score
//    first, MAX_PER_RUN per run, the rest picked up on the next hourly run.

const SILENCE_HOURS = 12;
const MAX_SILENCE_HOURS = 24 * 40;   // must stay <= the Fetch Recent Comms window
const MAX_PER_RUN = 8;
const TERMINAL = ['WON', 'LOST', 'DISQUALIFIED'];
const MARKER = '[SILENCE-ESCALATED]';

const now = Date.now();
const cutoff = now - SILENCE_HOURS * 3600000;
const staleBefore = now - MAX_SILENCE_HOURS * 3600000;

const digitsOf = (v) => String(v == null ? '' : v).replace(/[^0-9]/g, '');
const norm = (v) => String(v == null ? '' : v).trim().toLowerCase();
// Last 9 digits is the same country-code-safe comparison Resolve Lead Identity
// uses in the WhatsApp workflow (+9715..., 009715..., 05... all collapse).
const tail = (d) => (d.length >= 9 ? d.slice(-9) : '');

function safeAll(nodeName) {
  try { return $(nodeName).all().map(i => i.json).filter(Boolean); }
  catch (e) { return []; }
}

// A lead with no email but a phone is a WhatsApp-only lead: it is exactly the
// population D1 is about, so it is kept, not dropped.
const leads = safeAll('Fetch Open Leads')
  .filter(l => l.email || l.phone)
  .filter(l => !TERMINAL.includes(String(l.status || '').trim().toUpperCase()));

const logs = safeAll('Fetch Recent Comms').filter(r => r.lead_email);
const contacts = safeAll('Fetch WhatsApp Contacts').filter(c => c && c.chat_id);

// ---- index every log row under every key it could be filed under ------------
const byKey = {};    // exact lower-cased lead_email -> rows
const byTail = {};   // last 9 phone digits         -> rows
for (const row of logs) {
  const key = norm(row.lead_email);
  if (!key) continue;
  (byKey[key] = byKey[key] || []).push(row);
  // '971501234567@c.us', '+971501234567@whatsapp.lead' and '+971501234567' all
  // carry the number. '<lid>@lid' does NOT - its digits are an opaque WhatsApp
  // id and would collide with a real number, so it is deliberately excluded.
  if (!key.endsWith('@lid')) {
    const t = tail(digitsOf(key.split('@')[0]));
    if (t) (byTail[t] = byTail[t] || []).push(row);
  }
}

// ---- whatsapp_contacts bridges a LID chat id back to a lead -----------------
const chatIdsByTail = {};
const chatIdsByEmail = {};
for (const c of contacts) {
  const id = norm(c.chat_id);
  if (!id) continue;
  const t = tail(digitsOf(c.phone));
  if (t) (chatIdsByTail[t] = chatIdsByTail[t] || []).push(id);
  const em = norm(c.lead_email);
  if (em) (chatIdsByEmail[em] = chatIdsByEmail[em] || []).push(id);
}

function identityKeys(lead) {
  const em = norm(lead.email);
  const d = digitsOf(lead.phone) || digitsOf(String(em).split('@')[0]);
  const t = tail(d);
  const keys = new Set();
  if (em) keys.add(em);
  if (d) {
    keys.add('+' + d + '@whatsapp.lead');
    keys.add(d + '@whatsapp.lead');
    keys.add(d + '@c.us');
    keys.add(d + '@s.whatsapp.net');
    keys.add(d);
    keys.add('+' + d);
  }
  for (const id of (t ? (chatIdsByTail[t] || []) : [])) keys.add(id);
  for (const id of (em ? (chatIdsByEmail[em] || []) : [])) keys.add(id);
  return { keys, tail: t, digits: d, email: em };
}

function rowsForLead(ident) {
  const seen = new Set();
  const rows = [];
  const add = (r) => {
    const k = r.id || (norm(r.lead_email) + '|' + r.created_at + '|' + String(r.message || '').slice(0, 60));
    if (seen.has(k)) return;
    seen.add(k);
    rows.push(r);
  };
  for (const k of ident.keys) for (const r of (byKey[k] || [])) add(r);
  if (ident.tail) for (const r of (byTail[ident.tail] || [])) add(r);
  return rows;
}

const ts = (r) => new Date(r.created_at || 0).getTime();
const isMarker = (r) => String(r.message || '').startsWith(MARKER);

const out = [];
for (const lead of leads) {
  const ident = identityKeys(lead);
  const rows = rowsForLead(ident);
  if (!rows.length) continue;

  // Markers are our own bookkeeping, not a message to the customer.
  const real = rows.filter(r => !isMarker(r));
  const outbound = real.filter(r => r.direction === 'outbound').sort((a, b) => ts(b) - ts(a));
  const inbound = real.filter(r => r.direction === 'inbound').sort((a, b) => ts(b) - ts(a));
  if (!outbound.length) continue;

  const lastOut = ts(outbound[0]);
  const lastIn = inbound.length ? ts(inbound[0]) : 0;

  if (lastIn >= lastOut) continue;       // they already replied
  if (lastOut > cutoff) continue;        // not silent long enough yet
  if (lastOut < staleBefore) continue;   // older than the window we can see

  // D3: a marker only counts for the episode it was written in.
  const lastMarker = rows.filter(isMarker).map(ts).sort((a, b) => b - a)[0] || 0;
  if (lastMarker >= lastOut) continue;

  const hours_silent = Math.floor((now - lastOut) / 3600000);
  // D2: the callee's trigger is inputSource:'passthrough' - it forwards THIS
  // item verbatim and ignores the Execute Workflow node's field mapping. The
  // Slack node routes on a top-level `reason`, so `reason` has to be on the item
  // itself or the alert lands in the hot-lead channel headed ':fire: Hot Lead'.
  const reason = 'Customer has gone silent for ' + hours_silent +
                 ' hours since our last message on ' + outbound[0].created_at;

  out.push({ json: {
    email: lead.email || (ident.digits ? '+' + ident.digits + '@whatsapp.lead' : null),
    name: lead.name || null,
    phone: lead.phone || null,
    ai_score: lead.ai_score ?? null,
    status: lead.status || null,
    vehicle_interest: lead.vehicle_interest || null,
    reason: reason,
    escalation_reason: reason,
    escalation_source: 'phase6_silence_detector',
    hours_silent: hours_silent,
    last_outbound_at: outbound[0].created_at,
    last_outbound_message: String(outbound[0].message || '').substring(0, 300),
    matched_on: Array.from(ident.keys).slice(0, 8).join(',')
  } });
}

// Highest-value silent leads first, then bound the run.
out.sort((a, b) => (b.json.ai_score || 0) - (a.json.ai_score || 0));
return out.slice(0, MAX_PER_RUN);

// Delivery Report - verify every claim this run is about to make.
//
// 30 Aug 2026: the old version only asked `j.error !== undefined`. The
// escalation sub-workflow does not throw when it fails - it returns
//   { status:'escalation_failed', escalated:false, delivery:{ status:'FAILED' } }
// with no top-level `error` at all. So a failed escalation passed the check,
// 'Mark as Escalated' wrote the permanent [SILENCE-ESCALATED] marker anyway,
// and (with the old all-history marker check) the lead was retired from the
// safety net having been escalated to nobody. That was the silent-drop path.
// The escalation claim is now judged on what the sub-workflow actually said.

function checkEscalation() {
  let items;
  try { items = $('Trigger Lead Escalation').all(); }
  catch (e) { return { ok: false, why: 'node did not run on this branch' }; }
  if (!items.length) return { ok: false, why: 'Execute Workflow produced no items' };
  const j = items[0].json || {};
  if (j.error !== undefined) {
    const m = (j.error && (j.error.message || j.error.description)) || j.error;
    return { ok: false, why: String(m).slice(0, 300) };
  }
  if (j.escalated === true) return { ok: true, why: '' };
  const d = j.delivery || {};
  const drop = (Array.isArray(d.dropped) && d.dropped.length) ? ' | ' + d.dropped.join('; ') : '';
  return { ok: false, why: ('sub-workflow returned status=' + (j.status || 'unknown') +
                            ', delivery=' + (d.status || 'none') +
                            (d.note ? ' (' + d.note + ')' : '') + drop).slice(0, 300) };
}

function checkMarker() {
  let items;
  try { items = $('Mark as Escalated').all(); }
  catch (e) { return { ok: false, why: 'node did not run on this branch' }; }
  if (!items.length) return { ok: false, why: 'node produced no items' };
  const j = items[0].json || {};
  if (j.error !== undefined) {
    const m = (j.error && (j.error.message || j.error.description)) || j.error;
    return { ok: false, why: String(m).slice(0, 300) };
  }
  return { ok: true, why: '' };
}

const esc = checkEscalation();
const results = [{
  what: 'lead escalation actually delivered to a human',
  critical: true,
  ok: esc.ok,
  why: esc.why
}];

// The marker is now gated on the escalation landing ('Escalation Landed?').
// When it did not land the marker is skipped ON PURPOSE so the lead stays in
// the safety net - that is a correct outcome, not a dropped step. Asking
// $('Mark as Escalated') on the failed branch would read a PREVIOUS loop
// iteration's data, so it is not asked at all.
if (esc.ok) {
  const m = checkMarker();
  results.push({
    what: '[SILENCE-ESCALATED] marker closing this silence episode',
    critical: false, ok: m.ok, why: m.why
  });
} else {
  results.push({
    what: '[SILENCE-ESCALATED] marker deliberately NOT written - lead stays in the safety net',
    critical: false, ok: true, why: ''
  });
}

const dropped = results.filter(r => !r.ok);
const fatal = dropped.filter(r => r.critical);
const status = fatal.length ? 'FAILED' : dropped.length ? 'PARTIAL' : 'SUCCESS';

return [{ json: {
  ...( $input.first().json || {} ),
  delivery: {
    status,
    verified: results.filter(r => r.ok).map(r => r.what),
    dropped: dropped.map(r => r.what + ' — ' + r.why),
    note: dropped.length
      ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
      : 'all ' + results.length + ' claimed steps verified',
  },
}, pairedItem: { item: 0 } }];
